<?php $serviceTotal=array_sum(array_map(fn($r)=>(float)$r['revenue'],$services));$productTotal=array_sum(array_map(fn($r)=>(float)$r['revenue'],$products));?>
<div class="section-heading"><div><div class="eyebrow">Resultados do estabelecimento</div><h1>Prestação de serviços e vendas</h1><p class="text-secondary mb-0">Serviços e produtos separados, com visão por profissional.</p></div></div>
<div class="card mb-4"><div class="card-body"><form class="row g-2 align-items-end" method="get"><div class="col-md-3"><label class="form-label">De</label><input class="form-control" type="date" name="from" value="<?=htmlspecialchars($from)?>"></div><div class="col-md-3"><label class="form-label">Até</label><input class="form-control" type="date" name="to" value="<?=htmlspecialchars($to)?>"></div><div class="col-md-4"><label class="form-label">Profissional</label><select class="form-select" name="professional_id"><option value="">Todos</option><?php foreach($professionalOptions as $p):?><option value="<?=(int)$p['id']?>" <?=$professionalId===(int)$p['id']?'selected':''?>><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Filtrar</button></div></form></div></div>
<div class="row g-3 mb-4"><div class="col-md-4"><div class="card metric-card"><div class="card-body"><div class="metric-label">Serviços</div><div class="metric-value">R$ <?=number_format($serviceTotal,2,',','.')?></div></div></div></div><?php if($productsEnabled):?><div class="col-md-4"><div class="card metric-card"><div class="card-body"><div class="metric-label">Produtos</div><div class="metric-value">R$ <?=number_format($productTotal,2,',','.')?></div></div></div></div><?php endif;?><div class="col-md-4"><div class="card metric-card"><div class="card-body"><div class="metric-label">Total produzido</div><div class="metric-value">R$ <?=number_format($serviceTotal+$productTotal,2,',','.')?></div></div></div></div></div>
<div class="card mb-4"><div class="card-header"><strong>Prestação de serviços</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Serviço</th><th>Profissional</th><th>Atendimentos</th><th>Receita</th></tr></thead><tbody><?php foreach($services as $r):?><tr><td><?=htmlspecialchars($r['service_name'])?></td><td><?=htmlspecialchars($r['professional_name']??'—')?></td><td><?=(int)$r['quantity']?></td><td>R$ <?=number_format((float)$r['revenue'],2,',','.')?></td></tr><?php endforeach;?><?php if(!$services):?><tr><td colspan="4"><div class="empty-state">Nenhum serviço concluído no período.</div></td></tr><?php endif;?></tbody></table></div></div>
<?php if($productsEnabled):?><div class="card mb-4"><div class="card-header"><strong>Vendas de produtos</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Produto</th><th>Profissional</th><th>Quantidade</th><th>Receita</th><th>Margem estimada</th></tr></thead><tbody><?php foreach($products as $r):?><tr><td><?=htmlspecialchars($r['product_name'])?></td><td><?=htmlspecialchars($r['professional_name']??'Balcão')?></td><td><?=number_format((float)$r['quantity'],3,',','.')?></td><td>R$ <?=number_format((float)$r['revenue'],2,',','.')?></td><td>R$ <?=number_format((float)$r['revenue']-(float)$r['cost'],2,',','.')?></td></tr><?php endforeach;?><?php if(!$products):?><tr><td colspan="5"><div class="empty-state">Nenhuma venda no período.</div></td></tr><?php endif;?></tbody></table></div></div><?php endif;?>
<div class="card"><div class="card-header"><strong>Produção por profissional</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Profissional</th><th>Serviços</th><?php if($productsEnabled):?><th>Produtos</th><?php endif;?><th>Total</th><th>Comissão total</th><th>Pendente</th></tr></thead><tbody><?php foreach($professionals as $p):$s=(float)$p['service_revenue'];$prod=(float)$p['product_revenue'];$comm=(float)($p['commission_total']??0);$pending=(float)($p['commission_pending']??0);?><tr><td><strong><?=htmlspecialchars($p['name'])?></strong></td><td><?=(int)$p['service_qty']?> · R$ <?=number_format($s,2,',','.')?></td><?php if($productsEnabled):?><td><?=(int)$p['sale_qty']?> · R$ <?=number_format($prod,2,',','.')?></td><?php endif;?><td>R$ <?=number_format($s+($productsEnabled?$prod:0),2,',','.')?></td><td>R$ <?=number_format($comm,2,',','.')?></td><td>R$ <?=number_format($pending,2,',','.')?></td></tr><?php endforeach;?></tbody></table></div></div>
